// Timezone lookup over the table embedded in lib/zones.json.
//
// The table is generated by ./gen/main.go from the operating system's own
// tzdata: each transition's offset, abbreviation and DST flag are read from the
// zone's TZif file, because Go's Location API does not expose isdst, and the
// footer's POSIX rule is expanded past the last explicit transition. Pinning the
// release is what keeps it current - earlier versions came from the build
// machine's ICU (which lagged and answered +01 for Morocco after tzdata made it
// permanent +00) and then from the host's tzdata (which lagged 2026e, the release
// that moved Manitoba to permanent EST).
//
// The table covers 2022-01-01T00:00:00Z .. 2041-01-01T00:00:00Z. Inside that
// window the offsets, abbreviations and DST flags are exact; outside it the
// nearest entry is used and the caller is told which one, because guessing
// silently is worse than saying so.
//
// Names are looked up case-insensitively through each record's `names` array, so
// aliases that share a behaviour (Asia/Calcutta, Asia/Kolkata, ...) resolve to one
// record. A moving record's first entry is the state at the window start, not a
// transition; it is skipped when reporting a nearby DST change.
//
// Entry shapes: a fixed record's `o` is [offsetMinutes, abbreviation, dst]; a
// moving record's `t` entries are [epochSeconds, offsetMinutes, abbreviation, dst].

import { SECONDS_PER_DAY, civilFromDays } from "./civil.js";

// Two days is comfortably more than any offset step (±14 h), so a transition
// further away than this cannot affect a given wall-clock reading.
const NEAR_WINDOW = 2 * SECONDS_PER_DAY;

// Convenience names the table does not carry: a model writes "UTC" far more
// often than "Etc/GMT". Anything the table does know (Etc/GMT and its aliases,
// Etc/UTC, GMT0) is answered by the table itself, so its own abbreviation wins.
const UTC_ALIASES = { utc: true, z: true, zulu: true, ut: true, gmt: true };
const UTC_ABBREVIATIONS = { utc: "UTC", z: "UTC", zulu: "UTC", ut: "UTC", gmt: "GMT" };

function recordOf(primary, entry, fixed) {
  const record = {
    primary: primary,
    names: entry.names,
    abbreviation: null,
    offset: null,
    transitions: null,
    fixedDst: false,
  };
  if (fixed) {
    record.offset = entry.o[0];
    record.abbreviation = entry.o[1];
    // Older tables (and any entry generated without zdump) carry two fields;
    // an absent flag means "not DST", which is right for a fixed zone.
    record.fixedDst = entry.o.length > 2 && entry.o[2] === true;
    return record;
  }
  record.transitions = entry.t;
  return record;
}

export function createZones(table) {
  const records = [];
  const byName = new Map();
  const allNames = [];
  const keys = Object.keys(table.fixed);
  for (let index = 0; index < keys.length; index += 1) {
    const record = recordOf(keys[index], table.fixed[keys[index]], true);
    records.push(record);
    for (let name = 0; name < record.names.length; name += 1) {
      byName.set(record.names[name].toLowerCase(), record);
      allNames.push(record.names[name]);
    }
  }
  const zoneKeys = Object.keys(table.zones);
  for (let index = 0; index < zoneKeys.length; index += 1) {
    const record = recordOf(zoneKeys[index], table.zones[zoneKeys[index]], false);
    records.push(record);
    for (let name = 0; name < record.names.length; name += 1) {
      byName.set(record.names[name].toLowerCase(), record);
      allNames.push(record.names[name]);
    }
  }

  const start = civilFromDays(Math.floor(table.from / SECONDS_PER_DAY));
  const end = civilFromDays(Math.floor(table.to / SECONDS_PER_DAY));
  const windowText = isoDate(start) + " to " + isoDate(end) + " (UTC)";

  function isoDate(civil) {
    const month = civil.month < 10 ? "0" + civil.month : String(civil.month);
    const day = civil.day < 10 ? "0" + civil.day : String(civil.day);
    return civil.year + "-" + month + "-" + day;
  }

  // stateAt returns the offset and abbreviation in effect at an instant. An
  // instant outside the window takes the first (respectively last) entry, which
  // is the nearest rule the output then reports.
  // entryState reads a table entry: [offset, abbreviation, dst]. A table written
  // before the DST flag was recorded has two fields, and "not DST" is the safe
  // reading for those.
  function entryState(entry, dstFallback) {
    return {
      offset: entry[1] === undefined ? entry[0] : entry[1],
      abbrev: entry[1] === undefined ? null : entry[2],
      dst: entry.length > 3 ? entry[3] === true : dstFallback,
    };
  }

  function stateAt(record, ts) {
    if (record.transitions === null) {
      return { offset: record.offset, abbrev: record.abbreviation, dst: record.fixedDst };
    }
    const list = record.transitions;
    if (ts < list[0][0]) {
      return entryState(list[0], false);
    }
    let low = 0;
    let high = list.length - 1;
    while (low < high) {
      const middle = (low + high + 1) >> 1;
      if (list[middle][0] <= ts) {
        low = middle;
      } else {
        high = middle - 1;
      }
    }
    return entryState(list[low], false);
  }

  // localOffsetMinutes reads the daemon's own timezone through Date's local
  // getters. It is the one reading the table cannot provide, so it is only used
  // for the "local" pseudo-zone and is never mixed into a table lookup.
  function localOffsetMinutes(ts) {
    const minutes = -new Date(ts * 1000).getTimezoneOffset();
    if (!isFinite(minutes)) {
      throw new Error("the daemon timezone cannot be read for that timestamp");
    }
    return minutes;
  }

  function lookup(name) {
    return byName.get(String(name).toLowerCase());
  }

  function resolve(name) {
    const text = String(name === undefined || name === null ? "" : name).trim();
    if (text === "") {
      return null;
    }
    const lower = text.toLowerCase();
    if (lower === "local") {
      return { kind: "local", label: "local" };
    }
    const record = lookup(lower);
    if (record) {
      // Label the zone the way the caller spelled it (case-corrected), not the
      // record's primary: Asia/Shanghai shares a record with Asia/Brunei.
      let label = text;
      for (let index = 0; index < record.names.length; index += 1) {
        if (record.names[index].toLowerCase() === lower) {
          label = record.names[index];
          break;
        }
      }
      return { kind: "table", label: label, primary: record.primary, record: record };
    }
    if (Object.prototype.hasOwnProperty.call(UTC_ALIASES, lower)) {
      return { kind: "utc", label: lower === "gmt" ? "GMT" : "UTC", abbreviation: UTC_ABBREVIATIONS[lower] };
    }
    return null;
  }

  function zoneOffset(zone, ts) {
    if (zone.kind === "utc") {
      return { offset: 0, abbrev: zone.abbreviation };
    }
    if (zone.kind === "local") {
      return { offset: localOffsetMinutes(ts), abbrev: "local" };
    }
    return stateAt(zone.record, ts);
  }

  // parts decomposes an instant into the zone's local calendar fields, plus
  // everything the tool output reports about it.
  function parts(zone, ts) {
    const state = zoneOffset(zone, ts);
    const minutes = state.offset;
    const localSeconds = Math.floor(ts) + minutes * 60;
    const days = Math.floor(localSeconds / SECONDS_PER_DAY);
    const civil = civilFromDays(days);
    let rest = localSeconds - days * SECONDS_PER_DAY;
    if (rest < 0) {
      rest += SECONDS_PER_DAY;
    }
    let outOfWindow = null;
    if (zone.kind === "table") {
      if (ts < table.from) {
        outOfWindow = "before";
      } else if (ts >= table.to) {
        outOfWindow = "after";
      }
    }
    // The table carries the flag tzdata reports for the segment this instant
    // falls in. Inferring it from the offset - "anything above the window's
    // minimum is DST" - reported zones that permanently left DST (Asuncion,
    // Vancouver, Edmonton) as still observing it.
    let dst = state.dst === true;
    if (zone.kind === "local") {
      // The daemon's own zone cannot be asked for isdst through Date. The
      // reading that works is "is this offset below the zone's standard one":
      // a six-month comparison marked winter as DST too, because January differs
      // from July just as July differs from January. Sample a year either side
      // and take the minimum as standard time.
      let standard = localOffsetMinutes(ts);
      for (let offset = -360; offset <= 360; offset += 30) {
        const sample = localOffsetMinutes(ts + offset * SECONDS_PER_DAY);
        if (sample < standard) {
          standard = sample;
        }
      }
      dst = localOffsetMinutes(ts) > standard;
    }
    return {
      ts: Math.floor(ts),
      offset: minutes,
      abbrev: state.abbrev,
      days: days,
      year: civil.year,
      month: civil.month,
      day: civil.day,
      hour: Math.floor(rest / 3600) % 24,
      minute: Math.floor(rest / 60) % 60,
      second: rest % 60,
      localSeconds: localSeconds,
      dst: dst,
      outOfWindow: outOfWindow,
    };
  }

  // localToInstant turns a wall-clock reading into an instant. A reading inside
  // a spring-forward gap does not exist: it is interpreted with the offset in
  // force before the gap, which is the same as shifting it forward by the gap
  // length, and the shift is reported. A reading in a fall-back overlap happens
  // twice: the earlier occurrence (the larger offset) is returned and reported.
  function localToInstant(zone, naive) {
    if (zone.kind === "utc") {
      return { ts: naive, gap: null, ambiguous: null };
    }
    if (zone.kind === "local") {
      const probe = localOffsetMinutes(naive);
      return { ts: naive - localOffsetMinutes(naive - probe * 60) * 60, gap: null, ambiguous: null };
    }
    const record = zone.record;
    if (record.transitions === null) {
      return { ts: naive - record.offset * 60, gap: null, ambiguous: null };
    }
    const list = record.transitions;
    const candidates = [];
    let gap = null;
    let ambiguous = null;
    for (let index = 0; index < list.length; index += 1) {
      const at = list[index][0];
      if (at - naive > NEAR_WINDOW || naive - at > NEAR_WINDOW) {
        continue;
      }
      const before = index === 0 ? list[0][1] : list[index - 1][1];
      const beforeAbbrev = index === 0 ? list[0][2] : list[index - 1][2];
      const after = list[index][1];
      const afterAbbrev = list[index][2];
      const localBefore = at + before * 60;
      const localAfter = at + after * 60;
      if (after > before && naive >= localBefore && naive < localAfter) {
        gap = { at: at, shiftMinutes: after - before, before: before, after: after, beforeAbbrev: beforeAbbrev, afterAbbrev: afterAbbrev };
      } else if (after < before && naive >= localAfter && naive < localBefore) {
        ambiguous = { at: at, first: before, second: after, firstAbbrev: beforeAbbrev, secondAbbrev: afterAbbrev };
      }
      candidates.push({ offset: before, abbrev: beforeAbbrev });
      candidates.push({ offset: after, abbrev: afterAbbrev });
    }
    if (candidates.length === 0) {
      const state = stateAt(record, naive);
      candidates.push({ offset: state.offset, abbrev: state.abbrev });
    }
    const valid = [];
    for (let index = 0; index < candidates.length; index += 1) {
      const ts = naive - candidates[index].offset * 60;
      const actual = stateAt(record, ts);
      if (actual.offset === candidates[index].offset && actual.abbrev === candidates[index].abbrev) {
        valid.push(ts);
      }
    }
    if (gap) {
      return { ts: naive - gap.before * 60, gap: gap, ambiguous: null };
    }
    if (valid.length >= 2) {
      const earlier = Math.min(valid[0], valid[1]);
      return { ts: earlier, gap: null, ambiguous: ambiguous };
    }
    if (valid.length === 1) {
      return { ts: valid[0], gap: null, ambiguous: null };
    }
    const state = stateAt(record, naive);
    return { ts: naive - state.offset * 60, gap: null, ambiguous: null };
  }

  // transitionNear describes the closest real DST/offset change to an instant,
  // when there is one within horizon seconds. Index 0 of a moving record is the
  // window-start state, not a transition, so the scan starts at 1.
  function transitionNear(zone, ts, horizon) {
    if (zone.kind !== "table" || zone.record.transitions === null) {
      return null;
    }
    const list = zone.record.transitions;
    let best = null;
    let bestDistance = Infinity;
    for (let index = 1; index < list.length; index += 1) {
      const distance = Math.abs(list[index][0] - ts);
      if (distance < bestDistance) {
        bestDistance = distance;
        best = index;
      }
    }
    if (best === null || bestDistance > horizon) {
      return null;
    }
    const before = list[best - 1];
    const after = list[best];
    return {
      at: after[0],
      upcoming: after[0] > ts,
      beforeOffset: before[1],
      beforeAbbrev: before[2],
      afterOffset: after[1],
      afterAbbrev: after[2],
      shiftMinutes: after[1] - before[1],
    };
  }

  // suggest offers close names for a lookup that failed, so the model can retry
  // instead of guessing. Scoring is cheapest-first: alias tail, substring, then
  // a bounded edit distance.
  function suggest(name, limit) {
    const needle = String(name === undefined || name === null ? "" : name).trim().toLowerCase();
    const bare = needle.indexOf("/") >= 0 ? needle.slice(needle.lastIndexOf("/") + 1) : needle;
    const found = [];
    for (let index = 0; index < allNames.length; index += 1) {
      const candidate = allNames[index];
      const lower = candidate.toLowerCase();
      let score = -1;
      if (lower === needle) {
        score = 0;
      } else if (lower.slice(-(needle.length + 1)) === "/" + needle) {
        score = 1;
      } else if (needle.length >= 3 && lower.indexOf(needle) >= 0) {
        score = 2;
      } else if (bare.length >= 3 && lower.indexOf(bare) >= 0) {
        score = 3;
      } else if (Math.abs(lower.length - needle.length) <= 3 && (editDistance(lower, needle) <= 2 || editDistance(bare, needle) <= 2)) {
        score = 4;
      }
      if (score >= 0) {
        found.push({ score: score, name: candidate });
      }
    }
    found.sort(function (left, right) {
      if (left.score !== right.score) {
        return left.score - right.score;
      }
      if (left.name.length !== right.name.length) {
        return left.name.length - right.name.length;
      }
      return left.name < right.name ? -1 : 1;
    });
    const chosen = [];
    for (let index = 0; index < found.length && chosen.length < limit; index += 1) {
      if (chosen.indexOf(found[index].name) < 0) {
        chosen.push(found[index].name);
      }
    }
    return chosen;
  }

  return {
    from: table.from,
    to: table.to,
    windowText: windowText,
    aliasCount: allNames.length,
    recordCount: records.length,
    resolve: resolve,
    suggest: suggest,
    parts: parts,
    localToInstant: localToInstant,
    transitionNear: transitionNear,
  };
}

// editDistance is Levenshtein over short IANA names; callers bound the length
// difference first, so the table stays small.
function editDistance(left, right) {
  if (left === right) {
    return 0;
  }
  let previous = [];
  for (let index = 0; index <= right.length; index += 1) {
    previous.push(index);
  }
  for (let row = 1; row <= left.length; row += 1) {
    const current = [row];
    for (let column = 1; column <= right.length; column += 1) {
      const cost = left.charAt(row - 1) === right.charAt(column - 1) ? 0 : 1;
      let best = previous[column] + 1;
      if (current[column - 1] + 1 < best) {
        best = current[column - 1] + 1;
      }
      if (previous[column - 1] + cost < best) {
        best = previous[column - 1] + cost;
      }
      current.push(best);
    }
    previous = current;
  }
  return previous[right.length];
}
